package org.eclipse.rdf4j.sail.lmdb.evaluation;

import static org.assertj.core.api.Assertions.assertThat;

import java.io.File;
import java.math.BigInteger;
import java.util.List;

import org.eclipse.rdf4j.model.IRI;
import org.eclipse.rdf4j.model.Literal;
import org.eclipse.rdf4j.model.ValueFactory;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.model.vocabulary.XSD;
import org.eclipse.rdf4j.query.BindingSet;
import org.eclipse.rdf4j.query.QueryResults;
import org.eclipse.rdf4j.repository.sail.SailRepository;
import org.eclipse.rdf4j.repository.sail.SailRepositoryConnection;
import org.eclipse.rdf4j.sail.lmdb.LmdbStore;
import org.eclipse.rdf4j.sail.lmdb.config.LmdbStoreConfig;
import org.eclipse.rdf4j.sail.lmdb.inlined.Values;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

/**
 * Computed inline ids must be id-equal to the ids the store mints for the same values under every store encoding.
 * Stores default to the value-ordered ({@code ordered-v1}) integer encoding while the expression tier historically
 * minted legacy ZigZag ids, so a computed {@code STRLEN} result was never {@code sameTerm}-equal to a stored integer on
 * a default store. The first test pins the end-to-end behavior on a real (ordered) store; the second pins
 * {@code packInline} to the store's own encoder for a sample of every inlineable value family under both encodings.
 */
public class LmdbNativeInlineIdEncodingTest {

	private static final String EX = "http://example.com/";
	private static final String NATIVE_FLAG = "rdf4j.lmdb.nativeQueryEngine.enabled";

	@TempDir
	File dataDir;

	private SailRepository repository;

	@BeforeEach
	public void setUp() {
		repository = new SailRepository(new LmdbStore(dataDir, new LmdbStoreConfig("spoc,posc,ospc")));
		try (SailRepositoryConnection conn = repository.getConnection()) {
			ValueFactory vf = conn.getValueFactory();
			IRI label = vf.createIRI(EX, "label");
			IRI len = vf.createIRI(EX, "len");
			conn.add(vf.createIRI(EX, "s1"), label, vf.createLiteral("hello"));
			conn.add(vf.createIRI(EX, "s1"), len, vf.createLiteral(BigInteger.valueOf(5)));
		}
	}

	@AfterEach
	public void tearDown() {
		repository.shutDown();
	}

	private List<BindingSet> rows(String query, boolean nativeEnabled) {
		String previous = System.getProperty(NATIVE_FLAG);
		System.setProperty(NATIVE_FLAG, Boolean.toString(nativeEnabled));
		try (SailRepositoryConnection conn = repository.getConnection()) {
			return QueryResults.asList(conn.prepareTupleQuery(query).evaluate());
		} finally {
			if (previous == null) {
				System.clearProperty(NATIVE_FLAG);
			} else {
				System.setProperty(NATIVE_FLAG, previous);
			}
		}
	}

	@Test
	public void computedStrlenIsSameTermEqualToStoredInteger() {
		String query = "PREFIX ex: <" + EX + ">\n"
				+ "SELECT ?s WHERE { ?s ex:label ?l ; ex:len ?n . BIND(STRLEN(?l) AS ?k) "
				+ "FILTER(sameTerm(?k, ?n)) }";
		assertThat(rows(query, false)).as("generic engine").hasSize(1);
		assertThat(rows(query, true))
				.as("native engine: the computed STRLEN id must be id-equal to the stored integer id")
				.hasSize(1);
	}

	@Test
	public void packInlineMatchesStoreEncoderForBothEncodings() {
		ValueFactory vf = SimpleValueFactory.getInstance();
		Literal[] samples = {
				vf.createLiteral(BigInteger.ZERO),
				vf.createLiteral(BigInteger.valueOf(5)),
				vf.createLiteral(BigInteger.valueOf(-17)),
				vf.createLiteral(BigInteger.valueOf((1L << 54))),
				vf.createLiteral(BigInteger.valueOf(-(1L << 54))),
				vf.createLiteral("007", XSD.INTEGER),
				vf.createLiteral("ok"),
				vf.createLiteral("abcdef"),
				vf.createLiteral("abcdefgh"),
				vf.createLiteral(true),
				vf.createLiteral(false),
				vf.createLiteral(2.5d),
				vf.createLiteral(2.5f),
				vf.createLiteral("2024-01-01", XSD.DATE),
				vf.createLiteral("2024-01-01T10:30:00Z", XSD.DATETIME),
				vf.createLiteral("5", XSD.INT),
				vf.createLiteral("5", XSD.SHORT),
				vf.createLiteral("5.0", XSD.DECIMAL) };
		for (boolean ordered : new boolean[] { false, true }) {
			for (Literal sample : samples) {
				long storeId = Values.packLiteral(sample, ordered);
				if (storeId != 0L && !Values.unpackLiteral(storeId, vf).equals(sample)) {
					// the store itself would refuse this inline id (lexical form not preserved)
					storeId = 0L;
				}
				long computedId = LmdbNativeValueCodec.packInline(LmdbNativeValueCodec.fromValue(sample), ordered);
				if (storeId == 0L) {
					assertThat(computedId)
							.as("store would not inline %s (ordered=%s) — packInline must decline too", sample,
									ordered)
							.isEqualTo(NativeLmdbQuerySource.UNKNOWN_ID);
				} else {
					assertThat(computedId)
							.as("packInline must mint the store's id for %s (ordered=%s)", sample, ordered)
							.isEqualTo(storeId);
				}
			}
		}
	}
}
